def occurence(ch):
    f = open("sms.dat", "rb")
    eof = False
    occ = 0
    while not eof:
        try:
            e = load(f)
            if e["cin"] == ch:
                occ += 1
        except:
            eof = True
    f.close()
    return occ

def alpha(ch):
    i = 0
    ch = ch.upper()
    while i < len(ch) and ("A" <= ch[i] <= "Z" ):
        i += 1
    return i == len(ch)

